// par_decoder.cpp - prototype of a fully parallel union-find decoder (Vitis HLS).
//
// One processing element per node and per edge, as in Helios and Collision Clustering:
// every node holds its cluster label (the smallest node ID in its cluster) and every
// edge its growth, all in registers. The graph is wired in at synthesis time
// (src/par/par_graph.h, generated by python/gen_par_graph.py).
//
// Per growth iteration (the same growth as uf::decode in src/uf_core.h):
//   1. cluster parity and boundary flag per label, then "active" per node (passed up
//      and down a forest rooted at each label; see active_nodes)
//   2. growth rate of every edge, and the smallest step that fully grows an edge
//   3. every edge grows by rate * step at once
//   4. labels flood along grown edges (min label) until nothing changes
// Peeling: a forest of grown edges built level by level from all roots at once (the
// label of every cluster), parent = smallest-ID neighbour on the level above; then
// parities passed up one level per step.
//
// The boundary is split into PG virtual nodes with IDs 0..PG-1 (gen_par_graph.py
// --split-boundary), so no node has a large fan-in, and a cluster touches the boundary
// exactly when its label is below PG.
//
// The predictions equal tools/par_model.cpp's parallel-forest peeling
// --split-boundary K (par_expected.bin), which differs from the sequential reference
// only in which spanning forest is peeled.
//
// out[2s]   = predicted observable | status << 8 (0 OK, 1 cap hit, 2 invalid)
// out[2s+1] = growth iterations | flood steps << 8 | parity-forest steps << 20
//
// -DPAR_CROSSBAR_PARITY selects the earlier all-pairs parity (N^2 comparators).
// -DPAR_FUSED selects decode_fused: the same decoder as a single state machine.

#include <cstdint>

#include "par_graph.h"

namespace par {

#ifndef PAR_CROSSBAR_PARITY
// Cluster parity, local version: a forest of grown edges rooted at each label is built
// level by level (bfs_level), parity and the boundary flag are passed up to the root
// (cluster_up), and the root's "active" flag is passed back down (cluster_down). Every
// step only uses wires between neighbours; it costs about 3 x (cluster depth) cycles.
static bool active_nodes(const bool def[PN], const bool grown[PE], const lab_t lab[PN],
                         bool actn[PN], uint32_t& steps) {
#pragma HLS INLINE off
    bool reached[PN], par[PN];
    lvl_t lv[PN];
    bool pu[PE], pv[PE];
#pragma HLS ARRAY_PARTITION variable=reached complete
#pragma HLS ARRAY_PARTITION variable=par complete
#pragma HLS ARRAY_PARTITION variable=lv complete
#pragma HLS ARRAY_PARTITION variable=pu complete
#pragma HLS ARRAY_PARTITION variable=pv complete
    for (int v = 0; v < PN; ++v) {
#pragma HLS UNROLL
        reached[v] = lab[v] == v;
        lv[v] = 0;
        par[v] = def[v];
    }
    uint16_t depth = 0;
cl_levels:
    for (uint16_t l = 0; l < PN; ++l) {
#pragma HLS PIPELINE II=1
        if (!bfs_level(grown, reached, lv, pu, pv, l)) break;
        depth = l + 1;
    }
cl_up:
    for (uint16_t l = depth; l >= 1; --l) {
#pragma HLS PIPELINE II=1
        cluster_up(pu, pv, lv, par, l);
    }
    bool any = false;
    for (int v = 0; v < PN; ++v) {
#pragma HLS UNROLL
        actn[v] = (lab[v] == v) && v >= PG && par[v];   // label < PG: touches the boundary
        any |= actn[v];
    }
cl_down:
    for (uint16_t l = 0; l < depth; ++l) {
#pragma HLS PIPELINE II=1
        cluster_down(pu, pv, lv, actn, l);
    }
    steps += 3 * depth;
    return any;
}
#else
// Cluster parity per label (label = smallest node ID of the cluster), then whether
// each node's cluster is active (odd and not touching the boundary): an all-pairs
// comparison, fast but N^2 in hardware.
static bool active_nodes(const bool def[PN], const bool grown[PE], const lab_t lab[PN],
                         bool actn[PN], uint32_t& steps) {
#pragma HLS INLINE off
    bool actl[PN];
#pragma HLS ARRAY_PARTITION variable=actl complete
    bool any = false;
    for (int r = 0; r < PN; ++r) {
#pragma HLS UNROLL
        bool odd = false;
        for (int v = PG; v < PN; ++v) {
#pragma HLS UNROLL
            odd ^= (lab[v] == r) && def[v];
        }
        actl[r] = odd && r >= PG;   // label < PG: the cluster touches the boundary
        any |= actl[r];
    }
    for (int v = 0; v < PN; ++v) {
#pragma HLS UNROLL
        actn[v] = actl[lab[v]];
    }
    return any;
}
#endif

static void decode(const bool def[PN], uint32_t& w0, uint32_t& w1) {
#pragma HLS INLINE off
    lab_t lab[PN], nl[PN];
    bool grown[PE];
    uint8_t sup[PE], rate[PE];
    bool actn[PN];
#pragma HLS ARRAY_PARTITION variable=lab complete
#pragma HLS ARRAY_PARTITION variable=nl complete
#pragma HLS ARRAY_PARTITION variable=grown complete
#pragma HLS ARRAY_PARTITION variable=sup complete
#pragma HLS ARRAY_PARTITION variable=rate complete
#pragma HLS ARRAY_PARTITION variable=actn complete

    for (int v = 0; v < PN; ++v) {
#pragma HLS UNROLL
        lab[v] = (lab_t)v;
    }
    for (int e = 0; e < PE; ++e) {
#pragma HLS UNROLL
        grown[e] = false;
        sup[e] = 0;
    }

    uint32_t status = 0, iters = 0, floods = 0, csteps = 0;
grow:
    for (int it = 0; it < PE; ++it) {
        // 1. parity / boundary per label, then active per node
        const bool any = active_nodes(def, grown, lab, actn, csteps);
        if (!any) break;
        // 2. rates and the step
        edge_rate(lab, actn, grown, rate);
        const uint8_t step = grow_step(rate, sup);
        if (step == 255) { status = 2; break; }
        // 3. grow
        for (int e = 0; e < PE; ++e) {
#pragma HLS UNROLL
            if (rate[e]) {
                sup[e] += (rate[e] == 2) ? (uint8_t)(step << 1) : step;
                if (sup[e] >= PW2[e]) grown[e] = true;
            }
        }
        // 4. flood labels until stable
    flood_loop:
        for (int f = 0; f < PN; ++f) {
#pragma HLS PIPELINE II=1
            flood(lab, grown, nl);
            bool changed = false;
            for (int v = 0; v < PN; ++v) {
#pragma HLS UNROLL
                changed |= nl[v] != lab[v];
                lab[v] = nl[v];
            }
            ++floods;
            if (!changed) break;
        }
        ++iters;
        if (it == PE - 1) status = 1;
    }

    uint32_t obs = 0;
    if (status == 0) {
        bool reached[PN], res[PN];
        lvl_t lv[PN];
        bool pu[PE], pv[PE];
#pragma HLS ARRAY_PARTITION variable=reached complete
#pragma HLS ARRAY_PARTITION variable=res complete
#pragma HLS ARRAY_PARTITION variable=lv complete
#pragma HLS ARRAY_PARTITION variable=pu complete
#pragma HLS ARRAY_PARTITION variable=pv complete
        for (int v = 0; v < PN; ++v) {
#pragma HLS UNROLL
            // root: every label (a boundary cluster's label is a virtual boundary node)
            reached[v] = lab[v] == v;
            lv[v] = 0;
            res[v] = def[v];
        }
        uint16_t depth = 0;
    levels:
        for (uint16_t l = 0; l < PN; ++l) {
#pragma HLS PIPELINE II=1
            if (!bfs_level(grown, reached, lv, pu, pv, l)) break;
            depth = l + 1;
        }
    up:
        for (uint16_t l = depth; l >= 1; --l) {
#pragma HLS PIPELINE II=1
            obs ^= pass_up(pu, pv, lv, res, l);
        }
    }
    w0 = obs | (status << 8);
    w1 = (iters & 0xFF) | ((floods & 0xFFF) << 8) | (csteps << 20);
}


#ifdef PAR_FUSED
// The same decoder as one state machine: every phase of a growth iteration, and the
// peeling, is one state of a single loop pipelined at II = 1, so no cycles are lost
// entering and leaving short loops. One forest (reached / lv / pu, pv) serves the parity
// passes and the peeling. The flood stops when the labels did not change in the
// previous cycle (a comparison of registers, off the flood's own path), which costs one
// extra flood cycle but keeps the "anything changed?" OR out of the critical path.
// w1 = growth iterations | flood steps << 8 | state-machine cycles << 20
enum Phase : uint8_t { F_INIT, F_LEVEL, F_UP, F_ROOT, F_DOWN, RATE, STEP, GROW, FLOOD,
                       P_INIT, P_LEVEL, P_UP, DONE };

static void decode_fused(const bool def[PN], uint32_t& w0, uint32_t& w1) {
#pragma HLS INLINE off
    lab_t lab[PN], labp[PN];
    bool grown[PE], actn[PN], reached[PN], par[PN], res[PN];
    uint8_t sup[PE], rate[PE], pm[PPM];
    lvl_t lv[PN];
    bool pu[PE], pv[PE];
#pragma HLS ARRAY_PARTITION variable=lab complete
#pragma HLS ARRAY_PARTITION variable=labp complete
#pragma HLS ARRAY_PARTITION variable=grown complete
#pragma HLS ARRAY_PARTITION variable=actn complete
#pragma HLS ARRAY_PARTITION variable=reached complete
#pragma HLS ARRAY_PARTITION variable=par complete
#pragma HLS ARRAY_PARTITION variable=res complete
#pragma HLS ARRAY_PARTITION variable=sup complete
#pragma HLS ARRAY_PARTITION variable=rate complete
#pragma HLS ARRAY_PARTITION variable=pm complete
#pragma HLS ARRAY_PARTITION variable=lv complete
#pragma HLS ARRAY_PARTITION variable=pu complete
#pragma HLS ARRAY_PARTITION variable=pv complete
    // At the start every node is its own cluster, so the first parity pass is known:
    // a node is active exactly when it is a defect. Start at RATE; an empty shot is done.
    bool anydef = false;
    for (int v = 0; v < PN; ++v) {
#pragma HLS UNROLL
        lab[v] = (lab_t)v;
        labp[v] = (lab_t)v;
        actn[v] = def[v];   // def is false on the virtual boundary nodes
        anydef |= def[v];
    }
    for (int e = 0; e < PE; ++e) {
#pragma HLS UNROLL
        grown[e] = false;
        sup[e] = 0;
    }
    Phase ph = anydef ? RATE : DONE;
    lvl_t l = 0, depth = 0;
    uint8_t step = 0, sk = 0;
    bool first = true;
    bool lany = true;   // did the previous forest level add a node? (registered: keeps the
                        // chip-wide OR off the level counter's path, for one extra cycle)
    uint32_t status = 0, iters = 0, floods = 0, cycles = 0, obs = 0;
machine:
    for (;;) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=10 max=200
        ++cycles;
        if (ph == DONE) break;
        switch (ph) {
        case F_INIT:
        case P_INIT:
            for (int v = 0; v < PN; ++v) {
#pragma HLS UNROLL
                reached[v] = lab[v] == v;   // every label is a root
                lv[v] = 0;
                par[v] = def[v];
                res[v] = def[v];
            }
            l = 0;
            lany = true;
            ph = (ph == F_INIT) ? F_LEVEL : P_LEVEL;
            break;
        case F_LEVEL:
        case P_LEVEL:
            if (lany) {
                lany = bfs_level(grown, reached, lv, pu, pv, l);
                ++l;
            } else {   // level l - 1 added nothing: the forest has depth l - 1
                depth = l - 1;
                l = depth;
                if (ph == P_LEVEL) ph = (depth > 0) ? P_UP : DONE;
                else ph = (depth > 0) ? F_UP : F_ROOT;
            }
            break;
        case F_UP:
            cluster_up(pu, pv, lv, par, l);
            if (--l == 0) ph = F_ROOT;
            break;
        case F_ROOT: {
            bool any = false;
            for (int v = 0; v < PN; ++v) {
#pragma HLS UNROLL
                actn[v] = (lab[v] == v) && v >= PG && par[v];   // label < PG: boundary
                any |= actn[v];
            }
            l = 0;
            ph = !any ? P_INIT : (depth > 0) ? F_DOWN : RATE;
            break;
        }
        case F_DOWN:
            cluster_down(pu, pv, lv, actn, l);
            if (++l == depth) ph = RATE;
            break;
        case RATE:
            edge_rate(lab, actn, grown, rate);
            step_stage(0, rate, sup, pm);   // first stage of the minimum in the same cycle
            sk = 1;
            ph = STEP;
            break;
        case STEP:   // step minimum, one pipeline stage per cycle
            step_stage(sk, rate, sup, pm);
            if (++sk == PSTAGES) ph = GROW;
            break;
        case GROW:
            step = pm[PPM - 1];
            if (step == 255) { status = 2; ph = DONE; break; }
            for (int e = 0; e < PE; ++e) {
#pragma HLS UNROLL
                if (rate[e]) {
                    const uint8_t ns = sup[e] + ((rate[e] == 2) ? (uint8_t)(step << 1) : step);
                    sup[e] = ns;
                    if (ns >= PW2[e]) grown[e] = true;
                }
            }
            ++iters;
            first = true;
            ph = FLOOD;
            break;
        case FLOOD: {
            bool changed = first;
            for (int v = 0; v < PN; ++v) {
#pragma HLS UNROLL
                changed |= labp[v] != lab[v];   // what the previous flood step did
            }
            if (!changed) {   // flood finished: start the parity forest (F_INIT) now
                for (int v = 0; v < PN; ++v) {
#pragma HLS UNROLL
                    reached[v] = lab[v] == v;
                    lv[v] = 0;
                    par[v] = def[v];
                    res[v] = def[v];
                }
                l = 0;
                lany = true;
                ph = (iters >= PE) ? DONE : F_LEVEL;
                if (iters >= PE) status = 1;
                break;
            }
            lab_t nl[PN];
#pragma HLS ARRAY_PARTITION variable=nl complete
            flood(lab, grown, nl);
            for (int v = 0; v < PN; ++v) {
#pragma HLS UNROLL
                labp[v] = lab[v];
                lab[v] = nl[v];
            }
            first = false;
            ++floods;
            break;
        }
        case P_UP:
            obs ^= pass_up(pu, pv, lv, res, l);
            if (--l == 0) ph = DONE;
            break;
        default:
            ph = DONE;
            break;
        }
    }
    w0 = obs | (status << 8);
    w1 = (iters & 0xFF) | ((floods & 0xFFF) << 8) | (cycles << 20);
}
#endif

}  // namespace par

extern "C" void par_decoder(const uint32_t* dets, uint32_t* out, int num_shots) {
#pragma HLS INTERFACE m_axi port=dets offset=slave bundle=gmem0 depth=1024
#pragma HLS INTERFACE m_axi port=out offset=slave bundle=gmem1 depth=1024
#pragma HLS INTERFACE s_axilite port=dets
#pragma HLS INTERFACE s_axilite port=out
#pragma HLS INTERFACE s_axilite port=num_shots
#pragma HLS INTERFACE s_axilite port=return
    const int BLK = 64;   // shots per burst: inputs read and outputs written 64 shots at a time
    uint32_t wbuf[BLK * par::PDW];
    uint32_t obuf[2 * BLK];
#pragma HLS ARRAY_PARTITION variable=wbuf cyclic factor=par::PDW
blocks:
    for (int s0 = 0; s0 < num_shots; s0 += BLK) {
        const int nb = (num_shots - s0 < BLK) ? num_shots - s0 : BLK;
    rd:
        for (int i = 0; i < nb * par::PDW; ++i) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT max=64
            wbuf[i] = dets[s0 * par::PDW + i];
        }
    shots:
        for (int s = 0; s < nb; ++s) {
#pragma HLS LOOP_TRIPCOUNT max=64
            bool def[par::PN];
#pragma HLS ARRAY_PARTITION variable=def complete
            for (int v = 0; v < par::PN; ++v) {
#pragma HLS UNROLL
                const int i = v - par::PG;   // detector index; word i / 32 is in its own bank
                def[v] = (v >= par::PG) ? (bool)((wbuf[s * par::PDW + i / 32] >> (i % 32)) & 1) : false;
            }
            uint32_t w0, w1;
#ifdef PAR_FUSED
            par::decode_fused(def, w0, w1);
#else
            par::decode(def, w0, w1);
#endif
            obuf[2 * s] = w0;
            obuf[2 * s + 1] = w1;
        }
    wr:
        for (int i = 0; i < 2 * nb; ++i) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT max=128
            out[2 * s0 + i] = obuf[i];
        }
    }
}
